import os
from datetime import datetime, timezone
from typing import Dict, List, Optional, Union

import boto3


def get_metric_statistics(
    namespace: str,
    metric_name: str,
    start_time: Union[datetime, str],
    end_time: Union[datetime, str],
    period: int,
    statistics: Optional[List[str]] = None,
    dimensions: Optional[List[Dict[str, str]]] = None,
    region_name: Optional[str] = None,
    unit: Optional[str] = None,
) -> Dict:
    if statistics is None:
        statistics = ["Average"]

    if region_name is None:
        region_name = os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"

    def _to_datetime(value: Union[datetime, str]) -> datetime:
        if isinstance(value, datetime):
            dt = value
        else:
            s = value.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)

    cw = boto3.client("cloudwatch", region_name=region_name)

    params = {
        "Namespace": namespace,
        "MetricName": metric_name,
        "StartTime": _to_datetime(start_time),
        "EndTime": _to_datetime(end_time),
        "Period": period,
        "Statistics": statistics,
    }

    if dimensions:
        params["Dimensions"] = dimensions
    if unit:
        params["Unit"] = unit

    response = cw.get_metric_statistics(**params)

    datapoints = sorted(response.get("Datapoints", []), key=lambda x: x["Timestamp"])

    aggregates = {
        stat: [dp[stat] for dp in datapoints if stat in dp]
        for stat in statistics
    }

    return {
        "provider": "aws_cloudwatch",
        "region": region_name,
        "namespace": namespace,
        "metric_name": metric_name,
        "start_time": params["StartTime"].isoformat(),
        "end_time": params["EndTime"].isoformat(),
        "period": period,
        "unit": response.get("Label") if unit is None else unit,
        "label": response.get("Label"),
        "datapoints": [
            {
                "timestamp": dp["Timestamp"].astimezone(timezone.utc).isoformat(),
                **{stat: dp[stat] for stat in statistics if stat in dp},
                **({"Unit": dp["Unit"]} if "Unit" in dp else {}),
            }
            for dp in datapoints
        ],
        "aggregated_statistics": {
            stat: {
                "count": len(values),
                "min": min(values) if values else None,
                "max": max(values) if values else None,
                "sum": sum(values) if values else None,
                "average": (sum(values) / len(values)) if values else None,
            }
            for stat, values in aggregates.items()
        },
        "response_metadata": response.get("ResponseMetadata", {}),
    }
